        :param plaintext: The plaintext to encrypt, str.
        :param shift: The number of characters to shift each character in the plaintext, int.
        :return: The ciphertext, str.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'
        """
        cipher_text = ''
        for char in plaintext:
            if char == ' ':
                cipher_text += ' '
            elif  char.isupper():
                cipher_text += chr((ord(char) + shift - 65) % 26 + 65)
            else:
                cipher_text += chr((ord(char) + shift - 97) % 26 + 97)
        return cipher_text


    def vigenere_cipher(self, plaintext):
        """
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, str.
        :return: The ciphertext, str.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'
        """
        ciphertext = ""
        key_index = 0
        for char in plaintext:
            if char.isalpha():
                ascii_offset = 65 if char.isupper() else 97
                ciphertext += chr((ord(char) - ascii_offset + ord(self.key[key_index]) - ascii_offset) % 26 + ascii_offset)
                key_index = (key_index + 1) % len(self.key)
            else:
                ciphertext += char
        return ciphertext


    def rail_fence_cipher(self, plaintext, rails):
        if rails == 1:
            return plaintext

        dir_down = False
        rail_matrix = [[] for _ in range(rails)]

        row = 0
        for i in range(len(plaintext)):
            if row == 0 or row == rails - 1:
                dir_down = not dir_down
            rail_matrix[row].append(plaintext[i])
            if dir_down:
                row += 1
            else:
                row -= 1

        result = []
        for r in range(rails):
            result.append("".join(rail_matrix[r]))

        return "".join(result)

